"""Core v80 runs the Track 0 cases for sales with no Form 1099-B through the real coordinator.

v80 is package core-calculations v80, registry v78 and release v78 (Form
8949 boxes C and F, Schedule D lines 3 and 10). Every case below is a case
track0.py ran on the scratch v80, built by the same case builders, and run
here on the published v80 through live_coordinate_run and the presentation
model. The live marker is derived from that name.

- ``EXPECTED["v80"]``: each Track 0 case, with the hand values
  ``cf_prototype.check`` holds (gain, loss, wash and mixed returns), every
  attachment disposition, and no blocked line without a reason.
- ``EXPECTED["carried"]``: every v79 return of Track 0 on v80 under the new
  question's "no". Form 1040 lines 15 and 16 are the v79 dollars, except the
  returns Decisions 2, 3 and 5 accepted as newly blocked.

The published v79 pins stay in tests/test_noncovered_sales_v79.py.
Synthetic demo.* data only.
"""

from __future__ import annotations

import copy
import importlib.util
import json
import sys
from pathlib import Path
from tempfile import TemporaryDirectory
from types import SimpleNamespace
from typing import Any, Callable, cast

import pytest

from packages.derivation.live import live_coordinate_run
from packages.derivation.live_workspace import WorkspaceCapability
from packages.derivation.production_resolver import PublicationSurface

# Each case is one full live_coordinate_run (about 5 s to over a minute), so the
# module is an integration test and runs in the live lane.
pytestmark = pytest.mark.live

REPO = Path(__file__).resolve().parents[1]
EVIDENCE = REPO / "docs/phases/engine-breadth/milestones/f8949-boxes-cf-evidence"
TRACK0_MODULE = "f8949_boxes_cf_track0"
P = "tax.us.2025."
PACKAGE, PACKAGE_VERSION = "package.core-calculations.v80.json", "v80"
REGISTRY = "published-packages.v78.json"
RELEASE, RELEASE_VERSION = "demo.release.sli-worksheet-integration.2025.v78.json", "v78"
REPAIRS = {
    "q1_unbacked_yes", "old_ic_backed", "sale_needs_8949_no", "f8949_reads_lines_2_9",
    "nc_count_pairing", "amounts_agree",
}
Q2_QUESTION = (
    "Did you sell any stocks or other securities for which you did not receive a Form 1099-B "
    "or substitute statement?"
)
IN_CLASS_QUESTION = (
    "Apart from sales your broker reported with their basis, is every sale on your Form 8949 a sale "
    "of stocks or other securities, entered only once, with a basis you supply, net proceeds you "
    "supply when you got no Form 1099-B, and no adjustment other than a wash-sale loss?"
)
# Rejected before a run: a box C sale object without its basis (the sale's
# value schema), and a box B basis row without its own sale object (ADR-0082).
REJECTED = {
    "c_basis_object_missing": "'basis' is a required property",
    "d3_b_orphan_basis": "companion presence violated",
}
# v79 returns that v79 publishes and v80 blocks under the new "no".
# Decision 2: a Form 8949 "no" that no answer admits, with nothing recorded.
# Decision 3: a box B or E sale missing its proceeds or basis row.
# Decision 5: the Track 0 returns v79 computes wrongly or silently.
ACCEPTED_BLOCKS = {
    "boundary_no_without_member": 2,
    "probe_c_unrecorded_8949_no": 2,
    "probe_c_unrecorded_8949_no_other_no": 2,
    "probe_c_unrecorded_all_no": 2,
    "probe_e_basis_scalar_missing": 3,
    "probe_e_proceeds_scalar_missing": 3,
    "t0_q1_yes_nothing": 5,
    "t0_8949no_old_ic_yes_q1_no": 5,
    "t0_b_loss_8949_yes": 5,
    "t0_b_w_scalar_only_on_gain": 5,
}
T0_V79_CASES = ("t0_b_loss_8949_yes", "t0_q1_yes_nothing", "t0_8949no_old_ic_yes_q1_no", "t0_b_w_scalar_only_on_gain")
# The publishers that must carry exactly one disposition row in every run.
ONE_ROW = tuple(P + "rule." + name for name in (
    "schedule-d-line2", "schedule-d-line3", "schedule-d-line7", "schedule-d-line9", "schedule-d-line10",
    "schedule-d-line15", "schedule-d-line16", "schedule-d-line21", "form1040-line7a",
    "selected-preferential-base", "attachment.f8949", "attachment.schedule-d",
    "f1099b.noncovered-st-txn.amounts-check", "f1099b.noncovered-lt-txn.amounts-check",
    "f8949.no1099b-st-txn.amounts-check", "f8949.no1099b-lt-txn.amounts-check",
))
# Lines whose form field must carry explain text for the disposition shown.
EXPLAINED = {
    "schedule-d.line-2", "schedule-d.line-3", "schedule-d.line-7", "schedule-d.line-9",
    "schedule-d.line-10", "schedule-d.line-15",
}
Acts = list[dict[str, Any]]


@pytest.fixture(scope="module")
def world() -> SimpleNamespace:
    sys.path.insert(0, str(EVIDENCE))
    # tests/test_noncovered_sales_v79.py imports the noncovered evidence's own
    # ``track0``; this one is loaded under its own name so neither shadows the other.
    track0 = cast(Any, sys.modules.get(TRACK0_MODULE))
    if track0 is None:
        spec = importlib.util.spec_from_file_location(TRACK0_MODULE, EVIDENCE / "track0.py")
        assert spec is not None and spec.loader is not None
        track0 = importlib.util.module_from_spec(spec)
        sys.modules[TRACK0_MODULE] = track0
        spec.loader.exec_module(track0)
    cfp, cp = track0.cfp, track0.cp
    assert cfp.REPAIRS == REPAIRS
    cp.pin_v79()
    cp.install_v79_noncovered()
    content = cp.probe.CONTENT
    # The harness adopts the published vocabularies, not the prototype's copies.
    for key, name in (
        ("st", "f8949-no1099b-st.bundle.json"),
        ("lt", "f8949-no1099b-lt.bundle.json"),
        ("boundary", "schedule-d-boundary-form8949-in-class.bundle.json"),
        ("nc_check", "f1099b-noncovered-amounts-check.bundle.json"),
    ):
        cfp.BUNDLES[key] = json.loads((content / name).read_text(encoding="utf-8"))
    new: dict[str, Callable[[], Acts]] = {**cfp.new_cases(), **track0.track0_cases()}

    def carry(name: str) -> Callable[[], Acts]:
        return lambda: cast(Acts, cfp.with_q2(track0.v79_case(name), "no"))

    carried = {name: carry(name) for name in sorted(cfp.v79_cases()) + list(T0_V79_CASES)}
    return SimpleNamespace(track0=track0, cfp=cfp, cp=cp, new=new, carried=carried)


def _summary(world: SimpleNamespace, outcome: Any) -> dict[str, Any]:
    summary = cast(dict[str, Any], world.cp.summarize(outcome))
    if outcome.refusal is not None:
        return summary
    report = json.loads(outcome.output_path.read_text(encoding="utf-8"))
    model = json.loads(outcome.presentation_path.read_text(encoding="utf-8"))
    rows: dict[str, int] = {}
    for row in report.get("dispositions") or []:
        artifact = str(row.get("artifact_id", ""))
        if artifact in ONE_ROW:
            rows[artifact] = rows.get(artifact, 0) + 1
    summary["row_counts"] = rows
    no_reason, no_explain, questions = [], [], []
    for section in model.get("sections") or []:
        field = section.get("field") or {}
        resolved = section.get("resolved") or {}
        field_id = str(field.get("id") or "")
        disposition = str(resolved.get("disposition"))
        explain = str(((field.get("dispositions") or {}).get(disposition) or {}).get("explain") or "").strip()
        sentences = [str(r.get("sentence") or "").strip() for r in resolved.get("reasons") or [] if isinstance(r, dict)]
        questions += [s for s in sentences if s.endswith("?") and s not in questions]
        # A blocked line shows its field's blocked text and any reasons beside it.
        if disposition == "blocked" and not explain and not any(sentences):
            no_reason.append(field_id)
        if field_id.removeprefix(P) in EXPLAINED and not explain:
            no_explain.append(field_id)
    summary["blocked_without_reason"] = no_reason
    summary["missing_explain"] = no_explain
    # Every question in page order, untruncated.
    summary["questions"] = questions
    return summary


def _run(world: SimpleNamespace, build: Callable[[], Acts], run_id: str) -> dict[str, Any]:
    from tests.helpers import current_core_returns as ccr
    from tests.test_form_1099_k_income import _handover
    from tests.test_refund_or_amount_owed_track1 import _finish

    probe = world.cp.probe
    world.cfp.pin("v80")
    assert (probe.PACKAGE, probe.REGISTRY, probe.RELEASE) == (PACKAGE, REGISTRY, RELEASE)
    try:
        acts = build()
    except Exception as exc:  # noqa: BLE001 — a rejected recording is the expected outcome of two cases
        return {"error": type(exc).__name__, "message": str(exc)[:300]}
    surface = PublicationSurface(probe.RELEASE_DIR, probe.CONTENT / REGISTRY, probe.CONTENT)
    try:
        finished = _handover(
            _finish(
                copy.deepcopy(acts),
                package_path=probe.CONTENT / PACKAGE,
                package_version=PACKAGE_VERSION,
                release_path=probe.RELEASE_DIR / RELEASE,
                release_version=RELEASE_VERSION,
                note=run_id,
            ),
            surface=surface,
            reconfirm=True,
        )
        with TemporaryDirectory() as tmp:
            outcome = live_coordinate_run(
                WorkspaceCapability(Path(tmp) / "L"),
                repo_root=ccr.ROOT,
                authoritative_acts=finished,
                workspace_revision=len(finished),
                run_scope={"jurisdiction": "us", "year": probe.YEAR},
                scope_user=ccr.USER,
                request={"schema": "run-request.v1"},
                run_id=run_id,
                governance_pins=[],
                surface=surface,
                output_name="out.json",
            )
            return _summary(world, outcome)
    except Exception as exc:  # noqa: BLE001 — a rejected recording is the expected outcome of two cases
        return {"error": type(exc).__name__, "message": str(exc)[:300]}


def _projection(result: dict[str, Any]) -> dict[str, Any]:
    """The parts of a run the expectation table pins."""
    return {
        "error": result.get("error"),
        "lines": result.get("lines"),
        "attachments": result.get("attachments"),
        "questions": result.get("questions"),
    }


def _assert_sound(name: str, result: dict[str, Any]) -> None:
    assert result.get("presentation_valid") is True, result.get("presentation_error")
    assert result.get("stop_reason") == "saturated"
    assert result.get("duplicate_field_ids") == []
    assert result.get("missing_lines") == [], result.get("missing_lines")
    assert result.get("blocked_without_reason") == [], (name, result.get("blocked_without_reason"))
    assert result.get("missing_explain") == [], (name, result.get("missing_explain"))
    assert result.get("row_counts") == {artifact: 1 for artifact in ONE_ROW}, result.get("row_counts")


