@pytest.mark.parametrize("name", sorted(EXPECTED["v80"]))
def test_v80_matches_track0(world: SimpleNamespace, name: str) -> None:
    result = _run(world, world.new[name], f"demo.cf.t1.v80.{name}")
    expected = EXPECTED["v80"][name]
    if name in REJECTED:
        assert result.get("error") == "FindingModelError", result
        assert REJECTED[name] in str(result.get("message"))
        return
    assert result.get("error") is None, result.get("message")
    _assert_sound(name, result)
    assert world.cfp.check(name, result) == {}
    assert _projection(result) == expected


@pytest.mark.parametrize("name", sorted(EXPECTED["carried"]))
def test_v79_returns_on_v80_under_the_new_no(world: SimpleNamespace, name: str) -> None:
    result = _run(world, world.carried[name], f"demo.cf.t1.c80.{name}")
    expected = EXPECTED["carried"][name]
    if expected["error"] is not None:
        assert result.get("error") == expected["error"], result
        return
    assert result.get("error") is None, result.get("message")
    _assert_sound(name, result)
    assert _projection(result) == expected["v80"]
    lines = result["lines"]
    v80_form1040 = [lines["form1040.line-15"][1], lines["form1040.line-16"][1]]
    if name in ACCEPTED_BLOCKS:
        assert None not in expected["v79_form1040"]
        assert lines["form1040.line-15"][0] == lines["form1040.line-16"][0] == "blocked"
    else:
        assert v80_form1040 == expected["v79_form1040"]


def test_boundary_no_without_member_now_blocks_and_asks() -> None:
    """Decision 2: a Form 8949 "no" that no answer admits is no longer the wage return."""
    case = EXPECTED["carried"]["boundary_no_without_member"]
    assert case["v79_form1040"] == [34250, 3875]
    assert case["v80"]["lines"]["form1040.line-15"] == ["blocked", None]
    assert case["v80"]["attachments"] == {"f8949": "blocked", "schedule-d": "blocked"}
    assert IN_CLASS_QUESTION in case["v80"]["questions"]


def test_the_new_question_is_asked_when_unanswered() -> None:
    case = EXPECTED["v80"]["wage_q2_unanswered"]
    assert case["lines"]["form1040.line-15"] == ["blocked", None]
    assert Q2_QUESTION in case["questions"]


def test_expectation_table_covers_every_track0_case() -> None:
    assert len(EXPECTED["v80"]) == 71
    assert len(EXPECTED["carried"]) == 50
    assert set(ACCEPTED_BLOCKS) <= set(EXPECTED["carried"])
    assert set(REJECTED) <= set(EXPECTED["v80"])
